import csv as _csv
import json as _json
from collections import defaultdict
from datetime import date as _date
from datetime import timedelta as _td
from decimal import ROUND_HALF_EVEN as _EVEN
from decimal import ROUND_HALF_UP as _UP
from decimal import Decimal as _D
from pathlib import Path as _P

_Q_BOUNDS = [("Q1", _date(2026, 1, 1), _date(2026, 3, 31)), ("Q2", _date(2026, 4, 1), _date(2026, 6, 30)),
             ("Q3", _date(2026, 7, 1), _date(2026, 9, 30)), ("Q4", _date(2026, 10, 1), _date(2026, 12, 31))]
_Y0, _Y1 = _date(2026, 1, 1), _date(2026, 12, 31)
_SUM_FIELDS = ["activity_levy_cents", "floor_levy_cents", "payroll_levy_cents", "energy_levy_cents", "surcharge_cents",
               "primary_levy_cents", "gross_levy_cents", "credits_total_cents", "minimum_topup_cents", "net_levy_cents",
               "payments_cents", "interest_cents", "balance_cents"]


def _even(n, dnm):
    return int((_D(n) / _D(dnm)).to_integral_value(rounding=_EVEN))


def _up(n, dnm):
    return int((_D(n) / _D(dnm)).to_integral_value(rounding=_UP))


def _rows(path):
    with open(path, newline="", encoding="utf-8") as fh:
        return [dict(r) for r in _csv.DictReader(fh)]


def _iso(s):
    return _date.fromisoformat(s)


def _span(lo, hi):
    return max(0, (hi - lo).days + 1)


class _Batch:
    def __init__(self, root, R):
        self.root = _P(root)
        self.R = R
        meta = _json.loads((self.root / "batch.json").read_text(encoding="utf-8"))
        self.batch_id = meta["batch_id"]
        self.asof = _iso(meta["assessment_date"])
        self.tables = {n: _rows(self.root / f"{n}.csv") for n in
                       ("filers", "establishments", "receipts", "payroll", "energy", "credit_claims", "carryforwards", "payments")}
        self.group = defaultdict(lambda: defaultdict(list))
        for n, rows in self.tables.items():
            if n == "filers":
                continue
            for r in rows:
                self.group[r["filer_id"]][n].append(r)
        self.notes = []
        hol = set(R["holidays"])
        self.due = {}
        for q, nominal in (("Q1", _date(2026, 4, 30)), ("Q2", _date(2026, 7, 31)), ("Q3", _date(2026, 10, 31)), ("Q4", _date(2027, 1, 31))):
            x = nominal
            while x.isoformat() in hol or x.isoweekday() in (6, 7):
                x = x + _td(days=1)
            self.due[q] = x
        self.daily_rate = {}

    def rate_on(self, x):
        if x not in self.daily_rate:
            for p in self.R["interest_periods"]:
                if _iso(p["from"]) <= x and (p["to"] is None or x <= _iso(p["to"])):
                    self.daily_rate[x] = p["rate_ppm"]
                    break
        return self.daily_rate[x]

    def late_interest(self, amount, due, until):
        if amount <= 0:
            return 0
        acc = 0
        x = due + _td(days=1)
        while x <= until:
            acc += self.rate_on(x)
            x += _td(days=1)
        return _up(amount * acc, 365 * 1000000) if acc else 0

    def filer(self, F):
        R, fid = self.R, F["filer_id"]
        g = self.group[fid]
        start = max(_Y0, _iso(F["commenced_on"]))
        stop = min(_Y1, _iso(F["ceased_on"])) if F["ceased_on"] else _Y1
        days = _span(start, stop)
        windows = {}
        for e in g["establishments"]:
            lo = max(start, _iso(e["opened_on"]))
            hi = min(stop, _iso(e["closed_on"])) if e["closed_on"] else stop
            windows[e["establishment_id"]] = (lo, hi)
        dist_area = defaultdict(int)
        for e in g["establishments"]:
            lo, hi = windows[e["establishment_id"]]
            if hi >= lo:
                dist_area[e["district"]] += int(e["floor_area_m2"])
        if dist_area:
            principal = sorted(dist_area.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
        else:
            principal = F["registered_district"]
        pd = R["districts"][principal]

        known = R["classes"]
        lines, per_class, exports = [], defaultdict(int), 0
        for r in g["receipts"]:
            code = r["activity_code"] if r["activity_code"] in known else R["residual_class"]
            tag = f"{fid}/{r['establishment_id']}/{r['quarter']}"
            if r["activity_code"] not in known:
                self.notes.append(f"{tag}: unscheduled activity code {r['activity_code']} assessed under {R['residual_class']}")
            lo, hi = windows[r["establishment_id"]]
            qb = next(b for b in _Q_BOUNDS if b[0] == r["quarter"])
            if _span(max(lo, qb[1]), min(hi, qb[2])) == 0:
                self.notes.append(f"{tag}: receipts reported for an inactive establishment")
            gross, exp = int(r["gross_cents"]), int(r["export_cents"])
            exports += exp
            base = gross - (exp if known[code]["export_excluded"] else 0)
            lines.append([r["establishment_id"], r["activity_code"], code, r["quarter"], base])
            if base > 0:
                per_class[code] += base
        total_base = sum(per_class.values())
        pred = sorted(per_class.items(), key=lambda kv: (-kv[1], kv[0]))[0][0] if total_base > 0 else None
        band = known[pred]["band"] if pred else None

        se = False
        if F["small_enterprise_election"] == "Y":
            if F["filer_class"] == "public":
                self.notes.append(f"{fid}: small enterprise election by a public-class filer disregarded")
            else:
                se = total_base <= R["small_enterprise"]["threshold_cents"]
        out_lines, act = [], 0
        for eid, rep, code, q, base in sorted(lines, key=lambda x: (x[0], x[3], x[1])):
            ppm = known[code]["rates"][q]["rate_ppm"]
            if se:
                ppm = ppm * R["small_enterprise"]["rate_factor_percent"] // 100
            lv = _even(base * ppm, 1000000) if base > 0 else 0
            act += lv
            out_lines.append({"establishment_id": eid, "reported_code": rep, "assessed_code": code, "quarter": q,
                              "assessable_cents": base, "rate_ppm": ppm, "levy_cents": lv})

        factor = R["public_floor_factor_percent"] if F["filer_class"] == "public" else 100
        floor = 0
        for e in g["establishments"]:
            lo, hi = windows[e["establishment_id"]]
            for per in R["districts"][e["district"]]["rate_periods"]:
                n = _span(max(lo, _iso(per["from"])), min(hi, _iso(per["to"])))
                if n:
                    floor += _even(int(e["floor_area_m2"]) * per["rate_cents_per_m2"] * n * factor, 36500)

        P = R["payroll"]
        appr = sum(int(r["apprentice_payroll_cents"]) for r in g["payroll"])
        pbase = sum(int(r["payroll_cents"]) for r in g["payroll"]) - appr
        if F["entity_form"] in P["exempt_forms"]:
            payroll = 0
        else:
            mult = P["mutual_exemption_multiplier"] if F["filer_class"] == "mutual" else 1
            exempt = _even(P["annual_exemption_cents"] * mult * days, 365)
            payroll = _even((pbase - exempt) * P["rate_ppm"], 1000000) if pbase > exempt else 0

        egross = sum(_even(int(r["kwh"]) * R["energy_rates"][r["fuel"]][r["quarter"]], 1000) for r in g["energy"])
        energy = egross - (_even(egross * R["band_iii_energy_reduction_percent"], 100) if band == "III" else 0)

        rate = R["regional_surcharge"][pd["region"]] + (R["coastal_supplement_ppm"] if pd["coastal"] else 0)
        sur = _even((act + floor) * rate, 1000000)
        primary = act + floor + sur
        gross_levy = primary + payroll + energy

        any_edz = any(R["districts"][e["district"]]["edz"] for e in g["establishments"]
                      if windows[e["establishment_id"]][1] >= windows[e["establishment_id"]][0])
        specs = {c["credit_code"]: c for c in R["credits"]}

        def ok(c):
            el = c["eligibility"]
            checks = [
                F["filer_class"] in el.get("classes", [F["filer_class"]]),
                F["entity_form"] in el.get("forms", [F["entity_form"]]),
                F["entity_form"] not in el.get("excluded_forms", []),
                band in el.get("bands", [band]),
                se or not el.get("small_enterprise"),
                any_edz or not el.get("edz_any"),
                pd["coastal"] or not el.get("principal_coastal"),
                pd["edz"] or not el.get("principal_edz"),
                (not pd["coastal"]) or not el.get("principal_not_coastal"),
            ]
            if "class_or_form" in el:
                checks.append(F["filer_class"] in el["class_or_form"][0] or F["entity_form"] in el["class_or_form"][1])
            return all(checks)

        expenditure = defaultdict(int)
        for c in g["credit_claims"]:
            spec = specs.get(c["credit_code"])
            if spec is None:
                self.notes.append(f"{fid}: claim {c['claim_id']} under {c['credit_code']} disregarded: no such credit")
            elif spec["basis"] != "claim":
                self.notes.append(f"{fid}: claim {c['claim_id']} under {c['credit_code']} disregarded: credit arises without claim")
            else:
                expenditure[c["credit_code"]] += int(c["expenditure_cents"])
        brought = defaultdict(list)
        for c in g["carryforwards"]:
            spec = specs.get(c["credit_code"])
            y = int(c["origin_year"])
            if spec is None or not spec["carry_years"]:
                self.notes.append(f"{fid}: carryforward {c['credit_code']}/{y} disregarded: not permitted")
            elif y + spec["carry_years"] < 2026:
                self.notes.append(f"{fid}: carryforward {c['credit_code']}/{y} disregarded: expired")
            else:
                brought[c["credit_code"]].append([y, int(c["remaining_cents"])])

        room_levy = gross_levy
        room_global = _even(gross_levy * R["global_credit_cap_percent"], 100)
        bases = {"primary_levy": primary, "gross_levy": gross_levy, "payroll_levy": payroll, "energy_levy": energy}
        applied, carried = [], []
        for spec in R["credits"]:
            code = spec["credit_code"]
            queue = sorted(brought.get(code, []))
            current = 0
            if spec["basis"] == "claim":
                if code in expenditure:
                    if ok(spec):
                        current = _even(expenditure[code] * spec["rate_ppm"], 1000000)
                    else:
                        self.notes.append(f"{fid}: claim under {code} disregarded: filer not eligible")
            elif ok(spec):
                current = _even((appr if spec["basis"] == "apprentice_payroll" else exports) * spec["rate_ppm"], 1000000)
            if current:
                queue.append([2026, current])
            if not queue:
                continue
            cap = spec["cap"]
            room_cap = cap["amount"] if cap["basis"] == "fixed" else _even(bases[cap["basis"]] * cap["amount"], 1000000)
            for y, amt in queue:
                use = min(amt, room_cap, room_levy, room_global)
                use = use if use > 0 else 0
                if use:
                    applied.append({"credit_code": code, "origin_year": y, "applied_cents": use})
                room_cap, room_levy, room_global = room_cap - use, room_levy - use, room_global - use
                if amt - use and spec["carry_years"] and y + spec["carry_years"] >= 2027:
                    carried.append({"credit_code": code, "origin_year": y, "remaining_cents": amt - use})
        ctot = sum(a["applied_cents"] for a in applied)

        floor_min = _even(R["minimum_levy_cents"][F["entity_form"]] * days, 365)
        top = floor_min - (gross_levy - ctot) if floor_min > gross_levy - ctot else 0
        net = gross_levy - ctot + top

        q4 = net - 3 * (net // 4)
        plan = [{"quarter": q, "due": self.due[q], "amount": (q4 if q == "Q4" else net // 4), "paid": 0, "int": 0}
                for q in ("Q1", "Q2", "Q3", "Q4")]
        taken = 0
        for p in sorted(g["payments"], key=lambda p: (p["paid_on"], p["payment_id"])):
            when = _iso(p["paid_on"])
            if when > self.asof:
                self.notes.append(f"{fid}: payment {p['payment_id']} dated after the assessment date disregarded")
                continue
            left = int(p["amount_cents"])
            taken += left
            for inst in plan:
                gap = inst["amount"] - inst["paid"]
                if left <= 0:
                    break
                if gap <= 0:
                    continue
                part = gap if gap < left else left
                inst["paid"] += part
                inst["int"] += self.late_interest(part, inst["due"], when)
                left -= part
        for inst in plan:
            inst["int"] += self.late_interest(inst["amount"] - inst["paid"], inst["due"], self.asof)
        interest = sum(i["int"] for i in plan)

        return {
            "filer_id": fid, "filer_class": F["filer_class"], "entity_form": F["entity_form"], "principal_district": principal,
            "active_days": days, "predominant_class": pred, "band": band, "small_enterprise_applied": se,
            "activity_lines": out_lines, "activity_levy_cents": act, "floor_levy_cents": floor, "payroll_levy_cents": payroll,
            "energy_levy_cents": energy, "surcharge_cents": sur, "primary_levy_cents": primary, "gross_levy_cents": gross_levy,
            "credits_applied": applied, "credits_total_cents": ctot,
            "carryforward_out": sorted(carried, key=lambda c: (c["credit_code"], c["origin_year"])),
            "minimum_levy_cents": floor_min, "minimum_topup_cents": top, "net_levy_cents": net,
            "instalments": [{"quarter": i["quarter"], "due_date": i["due"].isoformat(), "amount_cents": i["amount"],
                             "paid_cents": i["paid"], "interest_cents": i["int"]} for i in plan],
            "payments_cents": taken, "interest_cents": interest, "balance_cents": net + interest - taken,
        }, pd["region"]


def expected_statements(root, R):
    b = _Batch(root, R)
    assessed = [(b.filer(F)) for F in sorted(b.tables["filers"], key=lambda f: f["filer_id"])]

    def tot(rows):
        return {k: sum(r[k] for r in rows) for k in _SUM_FIELDS}

    everyone = [a for a, _ in assessed]
    docs = {"summary.json": {
        "report_id": b.batch_id, "assessment_date": b.asof.isoformat(), "filer_count": len(everyone), "totals": tot(everyone),
        "region_totals": {rg: tot([a for a, r in assessed if r == rg]) for rg in ("North", "South", "West", "East")},
        "class_filer_counts": {c: len([a for a in everyone if a["filer_class"] == c]) for c in ("commercial", "mutual", "public")},
        "balance_status_counts": {"balance_due": len([a for a in everyone if a["balance_cents"] > 0]),
                                  "settled": len([a for a in everyone if a["balance_cents"] == 0]),
                                  "credit_balance": len([a for a in everyone if a["balance_cents"] < 0])}}}
    audit = _json.loads(_json.dumps(R["audit"]))
    audit["report_id"] = b.batch_id
    docs["policy_audit.json"] = audit
    t = b.tables
    docs["data_quality.json"] = {
        "input_file_count": sum(1 for p in b.root.iterdir() if p.is_file()), "filer_count": len(t["filers"]),
        "establishment_count": len(t["establishments"]), "receipts_line_count": len(t["receipts"]), "payroll_row_count": len(t["payroll"]),
        "energy_row_count": len(t["energy"]), "claim_count": len(t["credit_claims"]), "carryforward_count": len(t["carryforwards"]),
        "payment_count": len(t["payments"]), "quality_issue_count": len(b.notes), "quality_issues": sorted(b.notes)}
    for rg in ("North", "South", "West", "East"):
        mine = [a for a, r in assessed if r == rg]
        docs[f"region_{rg}.json"] = {"region": rg, "filer_count": len(mine), "totals": tot(mine), "filers": mine}
    for seg in ("commercial", "public"):
        mine = [a for a in everyone if a["filer_class"] == seg]
        ct = defaultdict(int)
        for a in mine:
            for c in a["credits_applied"]:
                ct[c["credit_code"]] += c["applied_cents"]
        docs[f"segment_{seg}.json"] = {"segment": seg, "filer_count": len(mine), "totals": tot(mine), "credit_totals": dict(ct),
                                       "filer_ids": [a["filer_id"] for a in mine]}
    return docs


